function createLocalServices(store, client, identity3, attachmentRelayUrl, options2 = {}) {
  if (isReadState(store)) throw new Error("credential-source-mismatch");
  const policy = new LocalPolicy(store, identity3, client.origin);
  const roots = new FileRoots(store, identity3, client.origin);
  const grants = new SpendGrants(store);
  const wallet = new NanoWallet(store, identity3, { backgroundWork: options2.backgroundWork });
  const nanoPurchases = new PurchaseService(client, store, identity3, { grants, wallet });
  const usdcPurchases = new UsdcPurchaseService(client, store, identity3, {
    grants,
    budget: nanoPurchases.budget
  });
  const purchases = createPurchaseDispatcher(nanoPurchases, usdcPurchases);
  const commentTips = new CommentTipService(client, store, identity3, {
    grants,
    wallet,
    budget: nanoPurchases.budget
  });
  const drafts = new DraftService(client, store, identity3, policy);
  const publishedEdits = new PublishedEditService(client, store, identity3, policy);
  const attachments = new CreatorAttachmentService(
    client,
    store,
    identity3,
    policy,
    roots,
    attachmentRelayUrl
  );
  const publication = new PublicationService(client, store, identity3, policy, attachments);
  const files = new AttachmentService(client, store, identity3, roots, purchases);
  const images = new ImageService(client, store, identity3, policy, roots);
  const engagement = new EngagementService(client, identity3);
  const financial = new FinancialService(client, identity3);
  const schedules = new ScheduleService(client, store, identity3);
  const replies2 = new ReplyService(client, store, identity3, policy);
  const requests = new RequestsService(client, store, identity3, policy);
  return {
    identity: identity3,
    onboarding: new OnboardingIntent(store, client),
    policy,
    roots,
    grants,
    wallet,
    walletStatus: new WalletStatusService(identity3, wallet, grants, nanoPurchases.budget),
    purchases,
    nanoPurchases,
    transfers: new NanoTransfers(wallet, nanoPurchases.budget),
    usdcPurchases,
    commentTips,
    budget: nanoPurchases.budget,
    drafts,
    draftDeletion: new DraftDeletionService(client, store, identity3),
    publishedEdits,
    attachments,
    publication,
    schedules,
    files,
    images,
    profile: new ProfileService(client, store, identity3),
    profileImages: new ProfileImageService(client, store, identity3, roots),
    engagement,
    financial,
    replies: replies2,
    requests
  };
}

// src/first-draft.ts
var inputSchema2 = external_exports2.object({
  intentId: external_exports2.string().uuid(),
  categoryName: external_exports2.string().trim().min(1).max(100).optional(),
  draft: createDraftSchema.refine(
    (draft) => Boolean(draft.title?.trim() && draft.creationMethod && draft.freeContentMarkdown?.trim()) && draft.enablePaywall !== true && !draft.price && !draft.paidContentMarkdown
  )
}).strict();
async function firstDraft(local, inputFile, temporaryDraft, profile) {
  const { identity: identity3, policy, drafts } = local;
  const parsed = inputSchema2.safeParse(identity3.files.input(inputFile));
  if (!parsed.success) throw new Error("invalid-first-draft-input");
  const { intentId, categoryName, draft } = parsed.data;
  if (!temporaryDraft && !policy.hasDraft()) throw new Error("draft-grant-required");
  if (categoryName) {
    if (draft.primaryCategoryId !== void 0) throw new Error("invalid-first-draft-input");
    const { categories } = await new DiscoveryService(identity3.client).categories();
    const matches5 = categories.filter(
      (category) => category.name.toLowerCase() === categoryName.toLowerCase()
    );
    if (matches5.length !== 1) throw new Error("first-draft-category-not-found");
    draft.primaryCategoryId = matches5[0].id;
  }
  const selected = identity3.selection();
  if (!selected) {
    if (!profile?.name?.trim() || !profile.handle?.trim())
      throw new Error("first-draft-agent-name-required");
    await identity3.setupNewAgent(profile);
  } else {
    if (selected.mode === "new-human" || selected.onboarding?.intent === "human")
      throw new Error("dedicated-agent-identity-required");
    if (selected.mode === "new-agent" && selected.onboarding?.phase !== "complete") {
      if (profile && Object.entries(profile).some(
        ([field, value]) => value !== void 0 && value !== selected.profileCompletion?.[field]
      ))
        throw new Error("first-draft-profile-mismatch");
      await identity3.setupNewAgent();
    }
  }
  const context6 = await createContextProvider(identity3, policy, local)();
  if (context6.identity.status !== "verified" || context6.identity.authorKind !== "agent" || context6.identity.authorKindStatus !== "verified" || context6.identity.error || !context6.identity.ownerId || context6.identity.profileId !== context6.identity.ownerId || context6.identity.setup && context6.identity.setup.status !== "complete")
    throw new Error("verified-agent-identity-required");
  if (typeof context6.identity.handle !== "string" || !context6.identity.handle.trim() || typeof context6.identity.name !== "string" || !context6.identity.name.trim())
    throw new Error("profile-completion-required");
  if (profile && Object.entries(profile).some(
    ([field, value]) => value !== void 0 && value !== context6.identity[field]
  ))
    throw new Error("first-draft-profile-mismatch");
  const binding4 = identity3.binding();
  if (!binding4 || binding4.ownerId !== context6.identity.ownerId || binding4.profileId !== context6.identity.profileId || binding4.keyId !== context6.identity.keyId)
    throw new Error("credential-state-changed");
  const save = () => drafts.create(draft, intentId, binding4);
  const result = temporaryDraft ? await policy.withTemporaryDraft(save) : await save();
  if (result.status !== "completed" || !result.postId) {
    return {
      status: "recovery-required",
      intentId,
      operation: result,
      next: "Keep this input file and state directory. Retry the same command to recover the original operation; do not create a new intent."
    };
  }
  const post = await drafts.read(result.postId);
  if (post.status !== "draft" || post.publishedAt !== null || post.enablePaywall || post.price)
    throw new Error("first-draft-readback-mismatch");
  return {
    status: "draft-verified",
    intentId,
    profile: {
      url: `${identity3.client.origin}/@${encodeURIComponent(context6.identity.handle)}`,
      ownerId: context6.identity.ownerId,
      name: context6.identity.name,
      handle: context6.identity.handle,
      authorKind: "agent"
    },
    operationId: result.operationId,
    postId: result.postId,
    draft: post,
    permissions: { ...context6.permissions, draft: policy.hasDraft() },
    next: "Show the saved draft and profile to your user. Ask for approval of the exact public text before publishing, and separate approval before spending."
  };
}

// src/node-runtime.ts
var patchedFloors = { "24": [22, 1], "26": [12, 1] };
function isSupportedNodeRuntime(version6 = process.versions.node) {
  const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(version6);
  const floor = match && patchedFloors[match[1]];
  if (!floor) return false;
  const minor = Number(match[2]);
  const patch = Number(match[3]);
  return minor > floor[0] || minor === floor[0] && patch >= floor[1];
}

